#include <algorithm>
#include <array>
#include <cstdint>
#include <iostream>
#include <limits>
#include <string>
#include <vector>

using namespace std;

int solve(const string& A, const string& B) {
    array<uint32_t, 20> original{};
    vector<int> letters;

    for (size_t i = 0; i < A.size(); ++i) {
        if (A[i] == B[i]) continue;

        int x = A[i] - 'a';
        int y = B[i] - 'a';

        original[x] |= uint32_t{1} << y;
        letters.push_back(x);
        letters.push_back(y);
    }

    if (letters.empty()) return 0;

    sort(letters.begin(), letters.end());
    letters.erase(unique(letters.begin(), letters.end()), letters.end());

    const int m = static_cast<int>(letters.size());
    const uint32_t full = (uint32_t{1} << m) - 1;

    array<int, 20> index;
    index.fill(-1);
    for (int i = 0; i < m; ++i) index[letters[i]] = i;

    vector<uint32_t> outgoing(m, 0);
    vector<uint32_t> incoming(m, 0);

    for (int i = 0; i < m; ++i) {
        int source = letters[i];

        for (int j = 0; j < m; ++j) {
            int target = letters[j];
            if (original[source] & (uint32_t{1} << target)) {
                outgoing[i] |= uint32_t{1} << j;
                incoming[j] |= uint32_t{1} << i;
            }
        }
    }

    const size_t states = size_t{1} << m;
    vector<uint32_t> reachable(states, 0);
    vector<uint8_t> crosses(states, 0);

    for (uint32_t mask = 1; mask <= full; ++mask) {
        uint32_t bit = mask & -mask;
        int vertex = __builtin_ctz(bit);
        reachable[mask] = reachable[mask ^ bit] | outgoing[vertex];
        crosses[mask] = (reachable[mask] & (full ^ mask)) != 0;
    }

    constexpr int INF = numeric_limits<int>::max() / 4;
    vector<array<int, 2>> dp(states, array<int, 2>{INF, INF});
    dp[0][0] = 0;

    for (uint32_t mask = 0; mask <= full; ++mask) {
        uint32_t remaining = full ^ mask;

        while (remaining) {
            uint32_t bit = remaining & -remaining;
            remaining ^= bit;

            int vertex = __builtin_ctz(bit);
            uint32_t nextMask = mask | bit;
            uint32_t after = full ^ nextMask;

            int finalContribution = (incoming[vertex] & after) != 0;

            for (int bad = 0; bad < 2; ++bad) {
                if (dp[mask][bad] == INF) continue;

                int nextBad = bad || ((outgoing[vertex] & mask) != 0);
                int prefixContribution =
                    nextMask != full && (nextBad || crosses[nextMask]);

                dp[nextMask][nextBad] =
                    min(dp[nextMask][nextBad],
                        dp[mask][bad] + finalContribution +
                            prefixContribution);
            }
        }
    }

    return min(dp[full][0], dp[full][1]);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    uint32_t T;
    cin >> T;

    while (T--) {
        size_t N;
        string A, B;
        cin >> N >> A >> B;
        cout << solve(A, B) << '\n';
    }

    return 0;
}

